"""2.2 · IP Studio performance on large models (generated by tools/gen-large-ip.js: 1 CPU + ~N/20 subsystems, ~1.4 links per node, 3 scenes × 12 steps).
Workflow measured: open (the overview) → select a group → open one group (double-click) → expand ALL → in the expanded diagram: select, click, search, scene step, edit (commit), undo.
Writes tests/perf_results_ip.json and checks budgets (exit 1 when exceeded).  Headless software-rendered Chromium: catches regressions, not device numbers.
   python tests/t_perf_ip.py [300 1000 ...]"""
import asyncio, json, pathlib, subprocess, sys
from util import *; from base_fs import *
ROOT_ = pathlib.Path(__file__).resolve().parent.parent
OUT = pathlib.Path(__file__).resolve().parent / 'perf_results_ip.json'
SIZES = [int(x) for x in sys.argv[1:]] or [300, 1000]
BUDGET = {  # ms
  300: {'open': 800, 'select_ov': 400, 'expand_one': 2000, 'expand_all': 9000, 'select': 300, 'click': 300, 'search': 300, 'step': 600, 'edit_same_width': 500, 'commit': 6000, 'undo': 6000, 'longtask': 4000, 'worker_cold_ms': 3000},
  1000: {'open': 1800, 'select_ov': 600, 'expand_one': 2500, 'expand_all': 60000, 'select': 800, 'click': 800, 'search': 500, 'step': 2000, 'edit_same_width': 1500, 'commit': 30000, 'undo': 30000, 'longtask': 20000, 'worker_cold_ms': 3000},
}
def gen(n):
    subprocess.run(['node', str(ROOT_ / 'tools/gen-large-ip.js'), str(n), '/tmp/_g%d.cbip' % n], capture_output=True, text=True, check=True); return pathlib.Path('/tmp/_g%d.cbip' % n).read_text('utf-8')
async def main():
    res = {}; fails = []
    for N in SIZES:
        fs = base_fs(); fs['C:\\Work\\Big'] = {'dir': 1}; P = 'C:\\Work\\Big\\big.cbip'; fs[P] = {'t': gen(N)}
        with Server() as srv:
            async with async_playwright() as p:
                b, ctx, pg, errs = await launch(p, srv, fs); ev = pg.evaluate
                async def wait(ms=200): await pg.wait_for_timeout(ms)
                await ev("window.__lt=[]; new PerformanceObserver(l=>l.getEntries().forEach(e=>window.__lt.push(e.duration))).observe({entryTypes:['longtask']})")
                await wait(500); R = {'nodes': N}; V = "ChipBench.app.current().viewer"; SEL = ".view-host:not(.hide) "
                async def frames(js):   # JS → two animation frames later
                    return round(await ev("(async()=>{const t=performance.now(); await (%s); await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))); return performance.now()-t;})()" % js))
                async def settle(): # how long until the page is quiet again (4 consecutive frames under 40 ms): the tail an operation leaves behind
                    return await ev("(async()=>{const t0=performance.now(); let quiet=0, last=performance.now(); while(quiet<4 && performance.now()-t0<30000){ await new Promise(r=>requestAnimationFrame(r)); const n=performance.now(); quiet = (n-last)<40 ? quiet+1 : 0; last=n; } return Math.round(performance.now()-t0);})()")
                async def until(count_js, cmp, limit=120000):
                    return await ev("(async()=>{const t0=performance.now(); while(performance.now()-t0<%d){ const n=%s; if(n %s) return Math.round(performance.now()-t0); await new Promise(x=>setTimeout(x,25)); } return -1;})()" % (limit, count_js, cmp))
                NODES = "document.querySelectorAll('.view-host:not(.hide) .ipb-node').length"
                R['worker_cold_ms'] = round(await ev("(async()=>{const t=performance.now(); await ChipBench.ipstudio.warm(); return performance.now()-t;})()"))   # what the idle pre-warm hides (the app starts it ~3.5 s after boot)
                R['open'] = round(await ev("(async()=>{const t=performance.now(); await ChipBench.openPath(%s); return performance.now()-t;})()" % json.dumps(P))); await pg.wait_for_selector(SEL + '.ipm .ipb-node', timeout=120000); await wait(700)
                R['overview_blocks'] = await ev(NODES); R['overview_links'] = await ev("document.querySelectorAll('.view-host:not(.hide) .ipb-edge').length"); R['banner'] = await ev("!!document.querySelector('.view-host:not(.hide) .ipm-big')"); R['dom'] = await ev("document.querySelectorAll('*').length")
                await ev("window.__lt.length=0")
                R['select_ov'] = await frames("%s.select('node','g3','detail')" % V)
                n0 = await ev(NODES); await ev("document.querySelector('.view-host:not(.hide) .ipb-node[data-id=\"g3\"]').dispatchEvent(new MouseEvent('dblclick',{bubbles:true}))")
                R['expand_one'] = await until(NODES, '> %d' % (n0 + 5), 60000); R['blocks_after_one'] = await ev(NODES); await wait(500)
                await ev("document.querySelector('.view-host:not(.hide) [data-a=collapse]').click()"); await wait(1200)   # back to the overview via the toolbar (toggles collapse-all)
                await ev("document.querySelector('.view-host:not(.hide) [data-a=collapse]').click()")
                R['expand_all_toolbar'] = await until(NODES, '> %d' % (N // 2), 120000)   # the toolbar button expands everything without the confirm
                R['expand_all'] = R['expand_all_toolbar']; R['blocks_expanded'] = await ev(NODES); R['svg_edges'] = await ev("document.querySelectorAll('.view-host:not(.hide) .ipb-edge').length"); R['dom_expanded'] = await ev("document.querySelectorAll('*').length")
                R['heap_mb'] = await ev("Math.round((performance.memory||{usedJSHeapSize:0}).usedJSHeapSize/1048576)")
                if R['expand_all'] < 0: R['note'] = 'expanded diagram did not appear within the limit'
                else:
                    await wait(800); await ev("window.__lt.length=0")
                    await settle()
                    R['select'] = await frames("%s.select('node','p3_5','detail')" % V); R['select_tail'] = await settle()
                    R['click'] = await frames("document.querySelector('.view-host:not(.hide) .ipb-node[data-id=\"p4_5\"]').dispatchEvent(new MouseEvent('click',{bubbles:true}))"); R['click_tail'] = await settle()
                    R['search'] = await frames("(()=>{const i=document.querySelector('.view-host:not(.hide) .ipm-find input'); i.value='IP 7.'; i.dispatchEvent(new Event('input'));})()"); R['search_tail'] = await settle()
                    R['search_hits'] = await ev("document.querySelectorAll('.view-host:not(.hide) .ipb-veil .ipb-node, .view-host:not(.hide) .ipb-node.fm').length")
                    await ev("(()=>{const i=document.querySelector('.view-host:not(.hide) .ipm-find input'); i.value=''; i.dispatchEvent(new Event('input'));})()"); await settle()
                    await ev("%s.scenes.pick('sc0')" % V); await settle(); R['step'] = await frames("%s.scenes.go(5)" % V); R['step_tail'] = await settle()
                    R['edit_same_width'] = await frames("%s.commit([{op:'set_param',node:'cpu',key:'k',value:1}],'param')" % V); R['edit_same_width_tail'] = await settle()   # does not change the graph: ELK cache hit
                    R['commit'] = await frames("%s.commit([{op:'update_node',id:'cpu',set:{name:'CPU 0'}}],'rename')" % V); R['commit_tail'] = await settle()   # changes a width: ELK runs again
                    R['undo'] = await frames("%s.undo()" % V); R['undo_tail'] = await settle()
                R['longtask'] = round(max([0] + await ev("window.__lt"))); R['longtasks_over_100'] = await ev("window.__lt.filter(x=>x>100).length")
                R['errors'] = [e[:160] for e in errs[:3]]
                await b.close()
        res[str(N)] = R; print(json.dumps(R, ensure_ascii=False))
        for k, lim in (BUDGET.get(N) or {}).items():
            v = R.get(k)
            if v is None: continue
            if v < 0 or v > lim: fails.append('%d nodes: %s = %s ms (budget %s)' % (N, k, v, lim))
        if R['errors']: fails.append('%d nodes: console errors %s' % (N, R['errors']))
        if not R['banner']: fails.append('%d nodes: no overview banner' % N)
    OUT.write_text(json.dumps(res, ensure_ascii=False, indent=1), 'utf-8')
    print(json.dumps({'passed': 0 if fails else 1, 'total': 1, 'fails': fails}, ensure_ascii=False)); sys.exit(1 if fails else 0)
asyncio.run(main())
